        assinantes = set(
            Assinatura.objects.filter(
                termo_id=termo_id, etapa="FISCAL_CONTRATO"
            ).values_list("usuario_id", flat=True)
        )
        destino = assinados if fiscais <= assinantes else pendentes
        destino.append(termo_id)

